#!/usr/bin/perl
# Differential fuzzer, round 1, strategy: case-folding.
# Ground truth: /workspace/dataset/test11_executable
# Under test:   /output/test11
# Compares stdout byte-exactly (files + cmp -s semantics via eq on raw bytes,
# plus a real cmp -s invocation for every mismatch) and the exit code.
#
# NOTE: no `use utf8` on purpose -- string literals in this file are raw UTF-8
# bytes, which is exactly what we want to hand to argv.

use strict;
use warnings;
use POSIX ();

my $CPP     = '/workspace/dataset/test11_executable';
my $RUST    = '/output/test11';
my $SCRATCH = '/tmp/wf-fuzz-r1-6';

mkdir $SCRATCH unless -d $SCRATCH;
my $CO = "$SCRATCH/cpp.out";
my $RO = "$SCRATCH/rust.out";
my $CE = "$SCRATCH/cpp.err";
my $RE = "$SCRATCH/rust.err";

# ------------------------------------------------------------------ helpers

sub u8 {    # code point -> raw UTF-8 bytes
    my $cp = shift;
    if    ($cp < 0x80)    { return chr($cp) }
    elsif ($cp < 0x800)   { return chr(0xC0 | ($cp >> 6)) . chr(0x80 | ($cp & 0x3F)) }
    elsif ($cp < 0x10000) {
        return chr(0xE0 | ($cp >> 12)) . chr(0x80 | (($cp >> 6) & 0x3F))
             . chr(0x80 | ($cp & 0x3F));
    }
    return chr(0xF0 | ($cp >> 18)) . chr(0x80 | (($cp >> 12) & 0x3F))
         . chr(0x80 | (($cp >> 6) & 0x3F)) . chr(0x80 | ($cp & 0x3F));
}

# Unicode-aware case mapping on a raw UTF-8 byte string; returns undef if the
# input is not decodable (we still fuzz the raw form separately).
sub map_case {
    my ($bytes, $which) = @_;
    my $s = $bytes;
    return undef unless utf8::decode($s);
    my $r;
    if    ($which eq 'uc') { $r = uc $s }
    elsif ($which eq 'lc') { $r = lc $s }
    elsif ($which eq 'tc') { $r = ucfirst lc $s }
    elsif ($which eq 'sw') {
        $r = join '', map { my $c = $_; (uc($c) eq $c) ? lc($c) : uc($c) }
                      split //, $s;
    }
    else { return undef }
    utf8::encode($r);
    return $r;
}

my @CASES;
my %SEEN;

sub add {
    my ($label, @args) = @_;
    my $key = join "\x00\x01", scalar(@args), @args;
    return if $SEEN{$key}++;
    push @CASES, [ $label, [@args] ];
}

sub addd {    # add() that tolerates undef (skips)
    my ($label, @args) = @_;
    for (@args) { return unless defined $_ }
    add($label, @args);
}

# ------------------------------------------------------- 1. every byte alone
my @CTX = ('%s', 'A%s', '%sA', 'A%sB', 'a%sb', 'Z%sz', '%s.COM',
           'EXAM%sPLE.CoM', 'xn--%sA', 'XN--%sA', '%s%s');
for my $b (1 .. 255) {
    my $bb = chr($b);
    for my $i (0 .. $#CTX) {
        my $t = $CTX[$i];
        $t =~ s/%s/$bb/g;
        add(sprintf('byte-0x%02x-ctx%d', $b, $i), $t);
    }
}

# --------------------------------------- 2. ASCII letters adjacent to high bytes
my @HIGH = (0x80, 0x9f, 0xa0, 0xbf, 0xc0, 0xc2, 0xc3, 0xc4, 0xcf, 0xdf,
            0xe0, 0xe1, 0xed, 0xef, 0xf0, 0xf4, 0xf5, 0xfe, 0xff);
my @LET = ('A','Z','a','z','I','i','S','s','K','k','@','[','`','{','0','9','.','-');
for my $h (@HIGH) {
    my $hb = chr($h);
    for my $L (@LET) {
        add(sprintf('adj-%02x-L',   $h), $hb . $L);
        add(sprintf('adj-L-%02x',   $h), $L . $hb);
        add(sprintf('adj-%02x-L-%02x', $h, $h), $hb . $L . $hb);
        add(sprintf('adj-L-%02x-L', $h), $L . $hb . $L);
    }
}

# ------------------------ 3. all-upper / all-lower / alternating base domains
my @BASES = (
    'example.com', 'test.example.com', 'localhost', 'xn--example.com',
    'xn--fiq228c.com', 'straße.de', 'ÄÖÜ.de', 'ΣΊΣΥΦΟΣ.gr', 'İstanbul.tr',
    'ǄǅǆǇǈǉǊǋǌ.hr', 'ＡＢＣ.ＣＯＭ', 'ＦＵＬＬＷＩＤＴＨ.ｊｐ',
    'ΟΔΟΣ.gr', 'ΑΣ.gr', 'ıI.tr', 'Iı.tr', 'İi.tr', 'ii̇.tr',
    'ＭｉＸｅＤ.Ｃｏｍ', 'ÀÁÂÃÄÅÆÇÈÉ.fr', 'ÊËÌÍÎÏÐÑÒÓ.fr',
    'ÔÕÖØÙÚÛÜÝÞ.fr', 'ΆΈΉΊΌΎΏ.gr', 'ЁЂЃЄЅІЇЈЉЊ.ru',
    'АБВГДЕЖЗИЙ.ru', 'ΪΫάέήί.gr', 'ǅǈǋ.hr', 'ﬀﬁﬂﬃﬄﬅﬆ.lig',
    'ΩKÅ.unit', 'ΩＫÅ.unit', 'ẛ.long-s', 'ẞ.de', 'ß.de', 'SS.de',
    'ⅠⅡⅢⅣⅤ.roman', 'ⅰⅱⅲⅳⅴ.roman', 'ᾼῌῼ.gr', 'ᾈᾉᾊ.gr',
    'ⓐⒶ.circ', 'ᏸᏹᏺ.chr', 'ႠႡႢ.geo', 'ⴀⴁⴂ.geo',
    '𐐀𐐁𐐂.des', '𐐨𐐩𐐪.des', 'Ꞌꞌꟼ.misc', 'ᵽᵾᵿ.misc',
    'Ä'.'A'.'ä'.'a', 'ẛ'.'S', 'İ'.'I'.'ı'.'i',
);
for my $raw (@BASES) {
    add('base', $raw);
    addd('uc',  map_case($raw, 'uc'));
    addd('lc',  map_case($raw, 'lc'));
    addd('tc',  map_case($raw, 'tc'));
    addd('sw',  map_case($raw, 'sw'));
    # byte-wise alternating ASCII case
    my @c = split //, $raw;
    for my $i (0 .. $#c) {
        my $o = ord $c[$i];
        if    ($o >= 0x41 && $o <= 0x5A && $i % 2 == 0) { $c[$i] = chr($o + 32) }
        elsif ($o >= 0x61 && $o <= 0x7A && $i % 2 == 1) { $c[$i] = chr($o - 32) }
    }
    add('bytealt', join('', @c));
    add('ace-lc',  'xn--' . $raw);
    add('ace-UC',  'XN--' . $raw);
    add('ace-Xn',  'Xn--' . $raw);
    add('ace-xN',  'xN--' . $raw);
    add('ace-dbl', 'xn--xn--' . $raw);
    # uppercase the ASCII bytes only, leave high bytes intact
    my $au = $raw; $au =~ tr/a-z/A-Z/; add('asciiup', $au);
    my $al = $raw; $al =~ tr/A-Z/a-z/; add('asciilo', $al);
}

# ------------------------------- 4. code points with non-trivial case mapping
my @TRICKY = (
    0x00C4, 0x00E4, 0x00DF, 0x1E9E, 0x0130, 0x0131, 0x0049, 0x0069,
    0x01C4, 0x01C5, 0x01C6, 0x01C7, 0x01C8, 0x01C9, 0x01CA, 0x01CB, 0x01CC,
    0x03A3, 0x03C3, 0x03C2, 0x0345, 0x0399, 0x1FBE,
    0x212A, 0x212B, 0x2126, 0x0307,
    0xFF21, 0xFF3A, 0xFF41, 0xFF5A, 0xFF10, 0xFF0E, 0xFF0D,
    0x0132, 0x0133, 0x0149, 0x017F,
    0x1E96, 0x1E97, 0x1E98, 0x1E99, 0x1E9A, 0x1E9B,
    0x1F88, 0x1F80, 0x1FFC, 0x1FD3, 0x1FE3,
    0x0587, 0x0535, 0x0582,
    0x10400, 0x10428, 0x104B0, 0x104D8, 0x1E900, 0x1E922,
    0x13A0, 0xAB70, 0x2170, 0x2160,
    0x00B5, 0x03BC, 0x039C, 0xA7C7, 0xA7C8, 0x0250, 0x2C6F,
);
for my $cp (@TRICKY) {
    my $ch = u8($cp);
    my $t  = sprintf 'cp-%04X', $cp;
    add("$t",           $ch);
    add("$t-dom",       $ch . '.com');
    add("$t-DOM",       $ch . '.COM');
    add("$t-mixA",      'A' . $ch . 'Z');
    add("$t-mixa",      'a' . $ch . 'z');
    add("$t-ace",       'xn--' . $ch);
    add("$t-ACE",       'XN--' . $ch);
    add("$t-rep",       $ch x 5);
    add("$t-repdot",    ($ch . '.') x 4);
    addd("$t-uc",       map_case($ch, 'uc'));
    addd("$t-lc",       map_case($ch, 'lc'));
    addd("$t-sw",       map_case($ch, 'sw'));
    my $n = length $ch;
    for my $i (0 .. $n - 1) {
        add("$t-b$i",       substr($ch, $i, 1));
        add("$t-b$i-wrapA", 'A' . substr($ch, $i, 1) . 'A');
        add("$t-b$i-wrapa", 'a' . substr($ch, $i, 1) . 'z');
    }
    for my $k (1 .. $n - 1) {
        add("$t-trunc$k",    substr($ch, 0, $k));
        add("$t-trunc$k-A",  substr($ch, 0, $k) . 'A');
        add("$t-trunc$k-a",  'a' . substr($ch, 0, $k) . 'Z');
        add("$t-tail$k",     substr($ch, $k));
        add("$t-tail$k-A",   'A' . substr($ch, $k) . 'B');
    }
}

# ------------------- 5. Latin-1 / CP1252 high bytes (uppercase in those sets)
for my $b (0xC0 .. 0xFF) {
    my $bb = chr($b);
    add(sprintf('latin1-%02x', $b),      $bb);
    add(sprintf('latin1-%02x-dom', $b),  $bb . '.COM');
    add(sprintf('latin1-%02x-word', $b), 'STRA' . $bb . 'E.DE');
}
for my $b (0x80 .. 0x9F) {
    my $bb = chr($b);
    add(sprintf('cp1252-%02x', $b),     $bb);
    add(sprintf('cp1252-%02x-mix', $b), 'Ab' . $bb . 'Cd');
}

# ------------------------------------------- 6. full-width alphabet sweeps
my $fwU = join '', map { u8(0xFF21 + $_) } 0 .. 25;
my $fwL = join '', map { u8(0xFF41 + $_) } 0 .. 25;
add('fw-upper', $fwU);
add('fw-lower', $fwL);
add('fw-mixed', join '', map { $_ % 2 ? u8(0xFF21 + $_) : u8(0xFF41 + $_) } 0 .. 25);
add('fw-upper-dom',  $fwU . '.COM');
add('fw-plus-ascii', $fwU . 'ABCdef');
add('ascii-plus-fw', 'ABCdef' . $fwL);
for my $i (0 .. 25) {
    add("fw-single-$i",     u8(0xFF21 + $i));
    add("fw-single-lo-$i",  u8(0xFF41 + $i));
    add("fw-single-mix-$i", 'X' . u8(0xFF21 + $i) . 'y');
}

# ---------------------------- 7. length boundaries from case-varying material
for my $n (1, 62, 63, 64, 65, 126, 127, 254, 255, 256, 257, 300) {
    add("len-upper-$n", 'A' x $n);
    add("len-lower-$n", 'a' x $n);
    add("len-alt-$n",   substr('Aa' x $n, 0, $n));
    add("len-high-$n",  substr("\xc3\x84" x $n, 0, $n));
    add("len-mix-$n",   substr("A\xc3\x84" x $n, 0, $n));
    add("len-fw-$n",    substr(u8(0xFF21) x $n, 0, $n));
    add("len-dots-$n",  substr('A.' x $n, 0, $n));
}
add('len-empty', '');

# --------------------------------------------- 8. xn-- prefix case permutations
for my $x ('x', 'X') {
    for my $nn ('n', 'N') {
        my $p = $x . $nn . '--';
        add("ace-perm-$p",       $p);
        add("ace-perm-$p-body",  $p . 'Fiq228C');
        add("ace-perm-$p-hi",    $p . u8(0x00C4) . '.DE');
        add("ace-perm-$p-dbl",   $p . $p . 'A');
    }
}
add('ace-x', 'x'); add('ace-xn', 'xn'); add('ace-xn-', 'xn-');
add('ace-only', 'xn--'); add('ace-only-upper', 'XN--');

# ------------------------------- 9. control chars / newlines / quotes + case
my @WEIRD = ("\n", "\r", "\r\n", "\t", ' ', '"', "'", "\\", "\x1b",
             "\x7f", "\x01", "\x0b", "\x0c");
for my $w (@WEIRD) {
    my $h = unpack 'H*', $w;
    add("weird-$h",     $w);
    add("weird-$h-up",  'ABC' . $w . 'DEF');
    add("weird-$h-lo",  'abc' . $w . 'def');
    add("weird-$h-hi",  u8(0x00C4) . $w . u8(0x0130));
    add("weird-$h-dom", 'EX' . $w . 'AMPLE.COM');
}

# ------------------------------------- 10. deterministic pseudo-random mixes
srand(0xC45E);
my @ALPHA = (
    (map { chr($_) } unpack 'C*', 'AZaz09.-_'),
    (map { chr($_) } (0x80, 0xBF, 0xC0, 0xC3, 0xDF, 0xE0, 0xEF, 0xF0, 0xFF)),
    (map { u8($_) } (0x00C4, 0x00DF, 0x0130, 0x0131, 0x01C4, 0x03A3,
                     0x03C2, 0xFF21, 0xFF41, 0x212A, 0x1E9E, 0x10400)),
    'xn--', 'XN--', 'Xn--',
);
for my $i (0 .. 799) {
    my $n = 1 + int(rand(22));
    my $a = join '', map { $ALPHA[ int(rand(scalar @ALPHA)) ] } 1 .. $n;
    add("rand-$i", $a);
}

# --------------------------------------------- 11. a few multi-argv cases
add('multi-1', 'ABC', "\xc3\x84", 'xn--Q');
add('multi-2', '', 'A', "\xff");
add('multi-3', u8(0x0130), u8(0x0131), 'SS', 'ss', "\xdf");
add('multi-4', "\n", "A\nB", "XN--\xc3\x9f");
add('multi-noargs');

# ------------------------------------------------------------------- runner

sub run_one {
    my ($bin, $outf, $errf, @args) = @_;
    my $pid = fork();
    die "fork: $!" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, '>', $outf) or POSIX::_exit(126);
        open(STDERR, '>', $errf) or POSIX::_exit(126);
        exec { $bin } $bin, @args;
        POSIX::_exit(127);
    }
    waitpid($pid, 0);
    return $?;
}

sub slurp {
    my $f = shift;
    open(my $fh, '<', $f) or return undef;
    binmode $fh;
    local $/;
    my $d = <$fh>;
    close $fh;
    return defined($d) ? $d : '';
}

sub esc {    # bytes -> printf '\xNN...' escape body
    my $s = shift;
    return join '', map { sprintf '\\x%02x', $_ } unpack 'C*', $s;
}

my $mm = 0;
my $n  = 0;
for my $case (@CASES) {
    my ($label, $args) = @$case;
    $n++;
    my $cst = run_one($CPP,  $CO, $CE, @$args);
    my $rst = run_one($RUST, $RO, $RE, @$args);
    my $co  = slurp($CO);
    my $ro  = slurp($RO);
    my $crc = $cst >> 8;
    my $rrc = $rst >> 8;
    my $csig = $cst & 127;
    my $rsig = $rst & 127;

    next if ($co eq $ro) && ($cst == $rst);

    $mm++;
    my $d = sprintf '%s/mm-%04d', $SCRATCH, $n;
    mkdir $d unless -d $d;
    open(my $f1, '>', "$d/cpp.out");  binmode $f1; print $f1 $co;  close $f1;
    open(my $f2, '>', "$d/rust.out"); binmode $f2; print $f2 $ro;  close $f2;
    my $cmpok = system('cmp', '-s', "$d/cpp.out", "$d/rust.out") == 0;

    print "==== MISMATCH #$mm  case=$n  label=$label\n";
    print "  argc=", scalar(@$args), "\n";
    for my $i (0 .. $#$args) {
        printf "  argv[%d] hex = %s\n", $i + 1, unpack('H*', $args->[$i]);
    }
    printf "  cpp  rc=%d sig=%d   rust rc=%d sig=%d\n", $crc, $csig, $rrc, $rsig;
    printf "  cpp  out hex = %s\n", unpack('H*', $co);
    printf "  rust out hex = %s\n", unpack('H*', $ro);
    printf "  cpp  out str = %s\n", $co;
    printf "  rust out str = %s\n", $ro;
    printf "  cmp -s agrees: %s\n", ($cmpok ? 'IDENTICAL(!?)' : 'DIFFER');
    my $ce = slurp($CE); my $re = slurp($RE);
    printf "  cpp  stderr = %s\n", $ce if defined($ce) && length($ce);
    printf "  rust stderr = %s\n", $re if defined($re) && length($re);
    # bash repro that preserves every byte including trailing newlines
    my @parts;
    for my $i (0 .. $#$args) {
        push @parts, sprintf(
            "IFS= read -r -d '' a%d < <(printf '%s\\x00')", $i, esc($args->[$i]));
    }
    my $vars = join ' ', map { "\"\$a$_\"" } 0 .. $#$args;
    print "  REPRO:\n";
    print "    $_\n" for @parts;
    print "    /workspace/dataset/test11_executable $vars > /tmp/wf-fuzz-r1-6/c.bin; echo \"cpp_rc=\$?\"\n";
    print "    /output/test11 $vars > /tmp/wf-fuzz-r1-6/r.bin; echo \"rust_rc=\$?\"\n";
    print "    cmp -s /tmp/wf-fuzz-r1-6/c.bin /tmp/wf-fuzz-r1-6/r.bin && echo SAME || echo DIFF\n";
    print "\n";
}

print "TOTAL CASES EXECUTED: $n\n";
print "TOTAL MISMATCHES: $mm\n";
exit 0;

