#!/usr/bin/perl
# Round-2 case-folding fuzzer: exhaustive byte sweeps + broad Unicode
# code-point sweep + locale sweep.  Usage: perl fuzz2.pl <mode>
#   mode = pairs   : every 2-byte argv (bytes 1..255 x 1..255)  -> 65025 cases
#   mode = triples : 3-byte args, ASCII letter in each position x every byte
#   mode = cps     : every code point in every case-mapped Unicode block
#   mode = locale  : case-folding inputs under many LC_ALL / LANG settings
use strict;
use warnings;
use POSIX ();

my $CPP  = '/workspace/dataset/test11_executable';
my $RUST = '/output/test11';
my $S    = '/tmp/wf-fuzz-r1-6';
my $mode = shift // 'pairs';

my ($CO, $RO, $CE, $RE) = ("$S/c2.out", "$S/r2.out", "$S/c2.err", "$S/r2.err");

sub u8 {
    my $cp = shift;
    return chr($cp) if $cp < 0x80;
    return chr(0xC0 | ($cp >> 6)) . chr(0x80 | ($cp & 0x3F)) if $cp < 0x800;
    return chr(0xE0 | ($cp >> 12)) . chr(0x80 | (($cp >> 6) & 0x3F))
         . chr(0x80 | ($cp & 0x3F)) if $cp < 0x10000;
    return chr(0xF0 | ($cp >> 18)) . chr(0x80 | (($cp >> 12) & 0x3F))
         . chr(0x80 | (($cp >> 6) & 0x3F)) . chr(0x80 | ($cp & 0x3F));
}

sub run_one {
    my ($bin, $outf, $errf, $env, @args) = @_;
    my $pid = fork();
    die "fork: $!" unless defined $pid;
    if ($pid == 0) {
        open(STDOUT, '>', $outf) or POSIX::_exit(126);
        open(STDERR, '>', $errf) or POSIX::_exit(126);
        if ($env) { $ENV{$_} = $env->{$_} for keys %$env }
        exec { $bin } $bin, @args;
        POSIX::_exit(127);
    }
    waitpid($pid, 0);
    return $?;
}

sub slurp {
    my $f = shift;
    open(my $fh, '<', $f) or return '';
    binmode $fh; local $/; my $d = <$fh>; close $fh;
    return defined($d) ? $d : '';
}

sub esc { join '', map { sprintf '\\x%02x', $_ } unpack 'C*', shift }

my $n = 0;
my $mm = 0;

sub check {
    my ($label, $env, @args) = @_;
    $n++;
    my $cst = run_one($CPP,  $CO, $CE, $env, @args);
    my $rst = run_one($RUST, $RO, $RE, $env, @args);
    my $co = slurp($CO);
    my $ro = slurp($RO);
    return if ($co eq $ro) && ($cst == $rst);
    $mm++;
    my $d = sprintf '%s/r2mm-%06d', $S, $n;
    mkdir $d unless -d $d;
    for my $p (["$d/cpp.out", $co], ["$d/rust.out", $ro]) {
        open(my $f, '>', $p->[0]); binmode $f; print $f $p->[1]; close $f;
    }
    my $differ = system('cmp', '-s', "$d/cpp.out", "$d/rust.out") != 0;
    print "==== MISMATCH #$mm case=$n label=$label mode=$mode\n";
    print "  env: ", join(' ', map { "$_=$env->{$_}" } sort keys %$env), "\n" if $env;
    printf "  argv[%d] hex = %s\n", $_ + 1, unpack('H*', $args[$_]) for 0 .. $#args;
    printf "  cpp rc=%d sig=%d  rust rc=%d sig=%d\n",
        $cst >> 8, $cst & 127, $rst >> 8, $rst & 127;
    printf "  cpp  out hex = %s\n", unpack('H*', $co);
    printf "  rust out hex = %s\n", unpack('H*', $ro);
    printf "  cpp  out str = %s", $co;
    printf "  rust out str = %s", $ro;
    printf "  cmp -s: %s\n", ($differ ? 'DIFFER' : 'IDENTICAL(exit-code-only)');
    print "  REPRO:\n";
    my @v;
    for my $i (0 .. $#args) {
        printf "    IFS= read -r -d '' a%d < <(printf '%s\\x00')\n", $i, esc($args[$i]);
        push @v, "\"\$a$i\"";
    }
    my $pre = $env ? join(' ', map { "$_='$env->{$_}'" } sort keys %$env) . ' ' : '';
    my $vs = join ' ', @v;
    print "    ${pre}$CPP $vs > $S/c.bin; echo \"cpp_rc=\$?\"\n";
    print "    ${pre}$RUST $vs > $S/r.bin; echo \"rust_rc=\$?\"\n";
    print "    cmp -s $S/c.bin $S/r.bin && echo SAME || echo DIFF\n\n";
    $| = 1;
}

if ($mode eq 'pairs') {
    for my $a (1 .. 255) {
        for my $b (1 .. 255) {
            check(sprintf('pair-%02x%02x', $a, $b), undef, chr($a) . chr($b));
        }
        printf STDERR "  ...lead byte %02x done (%d cases, %d mm)\n", $a, $n, $mm;
    }
}
elsif ($mode eq 'triples') {
    # every byte value flanked by, and flanking, each ASCII letter/case pivot
    my @piv = ('A', 'Z', 'a', 'z', 'I', 'i', 'S', 's');
    for my $b (1 .. 255) {
        my $bb = chr($b);
        for my $p (@piv) {
            check("t1-$b", undef, $p . $bb . $p);
            check("t2-$b", undef, $bb . $p . $bb);
            check("t3-$b", undef, $bb . $bb . $p);
            check("t4-$b", undef, $p . $bb . $bb);
            check("t5-$b", undef, 'xn--' . $p . $bb);
            check("t6-$b", undef, 'XN--' . $bb . $p);
        }
    }
}
elsif ($mode eq 'cps') {
    my @RANGES = (
        [0x0041, 0x007A], [0x00B5, 0x00FF], [0x0100, 0x024F],
        [0x0250, 0x02AF], [0x0300, 0x036F], [0x0370, 0x03FF],
        [0x0400, 0x052F], [0x0530, 0x058F], [0x10A0, 0x10FF],
        [0x13A0, 0x13FF], [0x1C80, 0x1CBF], [0x1D00, 0x1DBF],
        [0x1E00, 0x1EFF], [0x1F00, 0x1FFF], [0x2100, 0x214F],
        [0x2160, 0x218F], [0x24B6, 0x24E9], [0x2C00, 0x2D2F],
        [0xA640, 0xA7FF], [0xAB50, 0xABBF], [0xFB00, 0xFB17],
        [0xFF00, 0xFF5F], [0x10400, 0x1044F], [0x104B0, 0x104FB],
        [0x10570, 0x105BC], [0x10C80, 0x10CFF], [0x118A0, 0x118DF],
        [0x16E40, 0x16E7F], [0x1E900, 0x1E943],
    );
    for my $r (@RANGES) {
        for my $cp ($r->[0] .. $r->[1]) {
            next if $cp >= 0xD800 && $cp <= 0xDFFF;
            my $ch = u8($cp);
            check(sprintf('cp-%05X-bare', $cp), undef, $ch);
            check(sprintf('cp-%05X-wrap', $cp), undef, 'A' . $ch . 'Z.COM');
        }
        printf STDERR "  ...range %04X-%04X done (%d cases, %d mm)\n",
            $r->[0], $r->[1], $n, $mm;
    }
}
elsif ($mode eq 'locale') {
    my @LOCALES = qw(
        C POSIX C.utf8 en_US.utf8 en_US.iso88591 tr_TR.utf8 tr_TR.iso88599
        az_AZ.utf8 de_DE.utf8 de_DE.iso88591 el_GR.utf8 el_GR.iso88597
        ru_RU.utf8 ru_RU.koi8r lt_LT.utf8 ja_JP.utf8 ja_JP.eucjp zh_CN.utf8
        zh_CN.gb18030 ko_KR.euckr hr_HR.utf8 is_IS.utf8 fr_FR.iso885915
        sv_SE.iso88591 cs_CZ.iso88592 pl_PL.iso88592 hu_HU.iso88592
        lv_LV.iso885913 vi_VN.tcvn ar_SA.utf8 he_IL.utf8 th_TH.utf8
    );
    my @INP = (
        'I', 'i', "\xc4\xb0", "\xc4\xb1", 'STRASSE', "stra\xc3\x9fe",
        "\xc3\x9f", "\xc3\x84\xc3\x96\xc3\x9c", "\xce\xa3\xcf\x83\xcf\x82",
        "\xc3\x80\xc3\x81\xc3\x82", "\xef\xbc\xa1\xef\xbc\xa2",
        "\xc7\x84\xc7\x85\xc7\x86", 'ABCXYZ.COM', 'abcxyz.com',
        'AbCxYz.CoM', "\xff\xfe\xc0\xc1", "\xd0\x90\xd0\x91",
        "I\xcc\x87", "\xe2\x84\xaa\xe2\x84\xab", "SS", "\xc3\xa4",
        "\xdf\xde\xdd", "\xe0\xe1\xe2", "\xc9\xca\xcb",
    );
    for my $loc (@LOCALES) {
        for my $in (@INP) {
            check("loc-$loc", { LC_ALL => $loc, LANG => $loc, LC_CTYPE => $loc }, $in);
        }
        printf STDERR "  ...locale %s done (%d cases, %d mm)\n", $loc, $n, $mm;
    }
}
else { die "unknown mode $mode\n" }

print "TOTAL CASES EXECUTED: $n\n";
print "TOTAL MISMATCHES: $mm\n";
